pub fn is_palindrome(s: &str) -> bool {
    let mut start = 0;
    let mut end = s.len() - 1;
    while start < end {
        if !is_letter_or_digit(s[start]) || !is_letter_or_digit(s[end]) {
            start += 1;
            continue;
        }
        if s[start] != s[end] {
            return false;
        }
        start += 1;
        end -= 1;
    }
    true
}

fn is_letter_or_digit(c: char) -> bool {
    c.is_alphanumeric() || c.is_digit(10)
}

