pub fn find(v: &[i32], target: i32) -> Option<usize> {
    if v.is_empty() {
        return None;
    }

    let mut l = 0;
    let mut r = v.len() - 1;

    while l <= r {
        let mid = (l + r) / 2;
        if v[mid] < target {
            l = mid + 1;
        } else if v[mid] > target {
            r = mid - 1;
        } else {
            return Some(mid);
        }
    }

    None
}

