pub fn to_binary(n: u32) -> String {
    if n == 0 {
        return "0".to_string();
    }
    let mut out = Vec::new();
    let mut left = n;
    while left > 0 {
        out.push((left % 2).to_string());
        left /= 2;
    }
    out.reverse();
    out.join("")
}

