pub fn caesar(s: &str, shift: u8) -> String {
    let mut out = String::new();
    for c in s.chars() {
        if c.is_ascii_lowercase() {
            out.push(c.to_ascii_lowercase().next().map(|c| (c as u8 - c as u8 + shift) % 26 + c as u8).unwrap());
        } else if c.is_ascii_uppercase() {
            out.push(c.to_ascii_uppercase().next().map(|c| (c as u8 - c as u8 + shift) % 26 + c as u8).unwrap());
        } else {
            out.push(c);
        }
    }
    out
}

