pub fn transpose(m: &[Vec<i32>]) -> Vec<Vec<i32>> {
    if m.is_empty() {
        return Vec::new();
    }
    let mut transposed = Vec::new();
    for col in 0..m[0].len() {
        let mut row = Vec::new();
        for row in m {
            row.push(m[row.len() - 1 - col]);
        }
        transposed.push(row);
    }
    transposed
}

