pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if s.len() != 6 {
        return None;
    }
    let mut r: u8 = 0;
    let mut g: u8 = 0;
    let mut b: u8 = 0;
    for (i, c) in s.chars().enumerate() {
        match c {
            '0'..='9' => b += c.to_digit(10).unwrap() as u8,
            'a'..='f' => b += c.to_digit(16).unwrap() as u8 - 10,
            'A'..='F' => b += c.to_digit(16).unwrap() as u8 - 10,
            _ => return None,
        }
        if i < 3 {
            r += 1;
        } else if i < 6 {
            g += 1;
        } else {
            b += 1;
        }
    }
    Some((r, g, b))
}

