pub fn second_largest(v: &[i32]) -> Option<i32> {
    let mut unique = Vec::new();
    for &x in v {
        unique.push(x);
    }
    unique.sort_unstable();
    if unique.len() < 2 {
        None
    } else {
        Some(unique[unique.len() - 2])
    }
}

